class Solution {
  public long maxEnergyBoost(int[] energyDrinkA, int[] energyDrinkB) {
    long a = 0, b = 0, prevA = 0, prevB = 0;
    for (int i = 0; i < energyDrinkA.length; i++) {
      long na = Math.max(a, prevB) + energyDrinkA[i];
      long nb = Math.max(b, prevA) + energyDrinkB[i];
      prevA = a;
      prevB = b;
      a = na;
      b = nb;
    }
    return Math.max(a, b);
  }
}
